from fastapi import FastAPI, Header
from fastapi.responses import JSONResponse

app = FastAPI()

@app.get("/protected")
async def protected_route(authorization: str = Header(...)):
    return {"message": "Access granted", "token": authorization}

@app.post("/data")
async def create_data(content_type: str = Header(...)):
    if "json" not in content_type:
        return JSONResponse(status_code=400, content={"error": "Invalid content type"})
    return {"message": "Data received"}

@app.get("/cached")
async def get_cached_data():
    return JSONResponse(
        content={"data": "cached value"},
        headers={"Cache-Control": "max-age=3600", "X-Custom-Header": "value"}
    )
